Set-Location -LiteralPath $PSScriptRoot
$msg = 'leads: manual Add lead matched on PHONE ALONE, and partial is not a tier. Two findings from the live dry run. First: POST /leads/create deduped on phone only, ignoring the last name - dedup_service is explicit that phone-only matching is wrong because a number can be a household, and its registry keys on phone plus last name. Ashton Jamon was flagged against Jennifer Breeder on nothing but a shared number, and every manual lead on a previously-used number was unusable on creation. Now matches phone AND last name, records the parent and reason, and never re-flags a lead a human resolved. Second, and more dangerous: tier partial is the importer placeholder meaning unclassified, and it is a truthy string - the repair used if not lead.tier, which would have released all 7372 unclassified Restland leads straight into outreach. Added _has_real_tier so partial, none and unknown all count as unclassified; every status restore now routes those back to the review queue, and the dry run reports how many rows would actually become sendable. Also decoupled the fifth duplicate-to-DNC coupling in the email cleanup sweep.'
& "$PSScriptRoot\deploy.ps1" -Message $msg
Write-Output ("DEPLOY_EXIT=" + $LASTEXITCODE)
